        return lo + ((_n() << 23) | _n()) % (hi - lo + 1)
    N = 200000
    K = 100
    D = 200000
    ID = 1000000
    SKEW = 1
    METHODS = ["GET", "GET", "GET", "POST", "PUT", "DELETE", "PATCH"]
