        if i >= len(BASE):
            p += "/" + str(r(1, ID))
        routes.append(METHODS[r(0, len(METHODS) - 1)] + ":" + p)
    out = []
    for _ in range(N):
        a = r(0, D - 1)
        if SKEW:
            a = min(a, r(0, D - 1))
        out.append(routes[a])
    return f"{N} {K}\n{'' ''.join(out)}\n"
